cards=[]
for slug,name,title,description,diagram in items:
 cards.append(f'''<article class="concept"><a class="thumbnail" href="./{slug}.html" aria-label="{title} 전체 시안 열기"><img src="./{slug}-desktop.png" alt="{title}의 실제 브라우저 화면" width="1440" height="1000" data-thumb="{slug}"></a><div class="concept-info"><div><h2>{title}</h2><p>{name} · {description}</p><a class="open" href="./{slug}.html">전체 시안 열기 ↗</a></div><svg viewBox="0 0 220 114" class="layout-map" fill="none" stroke="currentColor" stroke-width="1" aria-label="{title} 화면 배치 도식" role="img">{diagram}</svg></div></article>''')
html='''<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Unfold · 서로 다른 네 가지 웹 구조</title><link rel="icon" href="./assets/app-icon.png"><link rel="stylesheet" href="./fonts.css"><style>
*{box-sizing:border-box}body{margin:0;background:#eeede8;color:#252d27;font-family:Geist,-apple-system,BlinkMacSystemFont,'Apple SD Gothic Neo',sans-serif;-webkit-font-smoothing:antialiased}a{color:inherit;text-decoration:none}button{font:inherit;cursor:pointer}main{width:min(calc(100% - 80px),1450px);margin:0 auto;padding:32px 0}.board-header{display:flex;align-items:center;justify-content:space-between;padding-bottom:24px;border-bottom:1px solid #25372a33;font-size:11px;color:#70766d}.board-header img{width:110px;height:auto;filter:brightness(0)}.intro{display:flex;justify-content:space-between;align-items:end;gap:40px;padding:34px 0 30px}.intro h1{font-size:35px;font-weight:600;letter-spacing:-.05em;line-height:1.2;margin:0 0 14px}.intro p{font-size:12px;color:#747b71;line-height:1.8;margin:0}.controls{display:flex;align-items:center;gap:25px;flex-wrap:wrap;justify-content:flex-end}.view-toggle{display:flex;border:1px solid #25372a33;padding:4px;gap:4px}.view-toggle button{border:0;background:transparent;color:#64715f;font-size:11px;padding:11px 16px;min-height:40px}.view-toggle button[aria-pressed=true]{background:#29362b;color:#f8f7ed}.color-toggle{font-size:11px;display:flex;align-items:center;gap:7px;white-space:nowrap}.color-toggle input{accent-color:#29362b}.concepts{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));grid-auto-flow:dense;gap:24px}.concept{border:1px solid #25372a33;background:#faf9f3;overflow:hidden}.thumbnail{display:block;aspect-ratio:1440/1000;overflow:hidden;background:#f4f1e8;border-bottom:1px solid #25372a33}.thumbnail img{width:100%;height:100%;object-fit:cover;filter:grayscale(1);transition:transform .65s,filter .3s}.show-color .thumbnail img{filter:none}.concept:hover .thumbnail img{transform:scale(1.012)}.concept-info{padding:23px 24px;display:flex;align-items:center;justify-content:space-between;gap:20px}.concept-info h2{font-size:21px;font-weight:600;letter-spacing:-.04em;margin:0 0 8px}.concept-info p{font-size:10px;line-height:1.7;color:#77806e;margin:0}.open{display:inline-block;font-size:11px;margin-top:17px;text-decoration:underline;text-underline-offset:4px}.layout-map{width:145px;flex-shrink:0;color:#617059}.board-footer{display:flex;justify-content:space-between;gap:30px;font-size:10px;color:#77806e;line-height:1.8;margin-top:28px}.mode-full .thumbnail{aspect-ratio:auto;height:550px}.mode-full .thumbnail img{object-fit:contain}.mode-mobile .thumbnail{aspect-ratio:390/844;max-width:315px;margin:20px auto 0}.mode-mobile .concept{background:#e2e5da}.mode-mobile .concept-info{background:#faf9f3;border-top:1px solid #25372a33}.mode-mobile .concept-info h2{font-size:20px}:focus-visible{outline:3px solid #677948;outline-offset:4px}
@media(max-width:800px){main{width:calc(100% - 32px);padding-top:22px}.intro{display:block}.intro h1{font-size:28px}.controls{justify-content:flex-start;margin-top:20px;gap:18px}.concepts{grid-template-columns:1fr;gap:18px}.concept-info{padding:20px}.concept-info h2{font-size:20px}.concept-info p{max-width:230px}.layout-map{width:100px}.board-footer{display:block}.board-footer p{margin:12px 0}.board-header{font-size:9px}.mode-full .thumbnail{height:600px}}
@media(max-width:350px){.layout-map{width:76px}.concept-info{padding:18px}.concept-info h2{font-size:18px}.controls{gap:14px}.view-toggle button{padding:10px 12px;font-size:10px}}
</style></head><body><main><header class="board-header"><img src="./assets/logo-lilac.svg" alt="Unfold" width="1162" height="320"><span>판매 웹 구조 시안 · 2026.10.09</span></header><section class="intro"><div><h1>서로 다른 네 가지 웹 구조.</h1><p>첫 화면, 전체 구성, 모바일을 비교해 보세요.</p></div><div class="controls"><div class="view-toggle" role="group" aria-label="비교 화면"><button type="button" data-mode="desktop" aria-pressed="true">첫 화면</button><button type="button" data-mode="full" aria-pressed="false">전체 구성</button><button type="button" data-mode="mobile" aria-pressed="false">모바일</button></div><label class="color-toggle"><input type="checkbox" id="show-color">색상 표시</label></div></section><section class="concepts" aria-label="네 가지 구조 시안">'''+''.join(cards)+'''</section><footer class="board-footer"><p>같은 중립색과 실제 앱 화면을 사용해 배치와 탐색 방식을 비교했습니다.</p><p>원하는 펫 · 이미지·GIF·MP4 · 3D(GLB) 지원<br>기존 웹사이트와 분리한 디자인 시안입니다.</p></footer></main><script>
document.querySelectorAll('[data-mode]').forEach(button=>button.addEventListener('click',()=>{const mode=button.dataset.mode;document.body.classList.toggle('mode-full',mode==='full');document.body.classList.toggle('mode-mobile',mode==='mobile');document.querySelectorAll('[data-mode]').forEach(item=>item.setAttribute('aria-pressed',String(item===button)));document.querySelectorAll('[data-thumb]').forEach(image=>{image.src=`./${image.dataset.thumb}-${mode}.png`;image.width=mode==='mobile'?390:1440;image.height=mode==='mobile'?844:1000})}));document.querySelector('#show-color').addEventListener('change',event=>document.body.classList.toggle('show-color',event.target.checked));
</script></body></html>'''
